def componi(parti):
    """Somma più sezioni: parti = [(sezione, quota del bordo inferiore), ...]."""
    A = sum(s["A"] for s, _ in parti)
    yG = sum(s["A"] * (y0 + s["yG"]) for s, y0 in parti) / A
    Ix = sum(s["Ix"] + s["A"] * (y0 + s["yG"] - yG) ** 2 for s, y0 in parti)
    return {"A": A, "yG": yG, "Ix": Ix}
